import math

def skjkasdkd(lst):
    """
    You are given a list of integers. Return the sum of the digits of the largest prime number in the list.
    If there are no prime numbers in the list, return 0.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        limit = int(math.sqrt(n)) + 1
        for i in range(3, limit, 2):
            if n % i == 0:
                return False
        return True

    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num

    if max_prime is None:
        return 0
    # Sum the digits of max_prime
    s = str(max_prime)
    return sum(int(d) for d in s)

