def largest_smallest_integers(lst):
    """
    Return a tuple (largest_negative, smallest_positive) from the input list.
    largest_negative is the largest (closest to zero) negative integer; None if none exist.
    smallest_positive is the smallest positive integer; None if none exist.
    """
    largest_negative = None
    smallest_positive = None

    for num in lst:
        if num < 0:
            # Potential candidate for largest_negative
            if largest_negative is None or num > largest_negative:
                largest_negative = num
        elif num > 0:
            # Potential candidate for smallest_positive
            if smallest_positive is None or num < smallest_positive:
                smallest_positive = num

    return (largest_negative, smallest_positive)
