import re

def words_in_sentence(sentence: str) -> str:
    """
    Returns words from the sentence whose lengths are prime numbers, preserving order.
    """
    # Helper function to check if a number is prime
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Split sentence into words using whitespace (handles multiple spaces, etc)
    words = sentence.split()
    # Filter words by prime length and join them with spaces
    filtered_words = [w for w in words if is_prime(len(w))]
    return ' '.join(filtered_words)
